[605] = { en = "Singing Blue Shards", tier = 2,
  t = "Zingende blauwe scherven",
  d = "De Singing Crystals bestaan alleen in Stranglethorn, en voor bepaalde partijen zijn ze erg waardevol. Ik kan die kristallen verkopen, maar de vervloekte Venture Company maakt het voor een eerlijke ondernemer zoals ik moeilijk om er iets van te verzamelen!$B$BIk wil jou graag inhuren.$B$BDe basilisken in Stranglethorn eten het kristal. Daardoor hebben ze hun harde huid, en soms kun je er kristal van behoorlijke kwaliteit uit halen.$B$BJe kunt het van elke basilisk krijgen, maar de minder gemene zitten langs de oevers ten zuiden van Zul'Kunda, in het noorden.",
  o = "Breng 10 Singing Crystal Shards naar Crank Fizzlebub.",
  p = "Heb je die scherven al? Ik geef je een behoorlijk deel van de winst!",
  c = "Aha! Deze zijn prima, $N. Ja, heel prima!$B$BHier is je deel, en... het was een genoegen om zaken met je te doen.",
  g = { {"Zingende", "singing (zingen)"}, {"scherven", "shards (scherf)"}, {"bepaalde", "certain (bepaald)"}, {"partijen", "parties (partij)"}, {"waardevol", "valuable"}, {"ondernemer", "entrepreneur"}, {"inhuren", "to hire"}, {"basilisken", "basilisks (basilisk)"}, {"behoorlijke", "decent (behoorlijk)"}, {"gemene", "nasty (gemeen)"}, {"oevers", "shores (oever)"}, {"deel", "cut, share"}, {"winst", "profits"}, {"genoegen", "pleasure"} },
},

[195] = { en = "Raptor Mastery", tier = 3,
  t = "Meester in raptors",
  d = "Laten we de uitdaging nu wat zwaarder maken en kijken of je het aankunt. Ga de jungle in en schiet 10 van die verdomde Lashtail Raptors. Laat eens zien wat je kunt!",
  o = "Hemet Nesingwary wil dat je 10 Lashtail Raptors doodt.",
  p = "Een echte jager richt zich op zijn prooi. Jij, mijn vriend, lijkt meer bezig met kletsen rond het kampvuur. Ga nu naar buiten en dood 10 Lashtails, voordat ik zelf de hele verdomde jungle in één jacht van ze verlos.",
  c = "Zo krijg je een trofee of twee boven de oude haard! Mooi gejaagd, $N!",
  g = { {"uitdaging", "challenge"}, {"aankunt", "can handle (aankunnen)"}, {"schiet", "bag, shoot (schieten)"}, {"verdomde", "bloody, damned (verdomd)"}, {"richt zich op", "focuses on (zich richten op)"}, {"prooi", "prey"}, {"kletsen", "chit-chatting"}, {"kampvuur", "campfire"}, {"verlos", "rid (verlossen van)"}, {"trofee", "trophy"}, {"haard", "hearth"} },
},

[213] = { en = "Hostile Takeover", tier = 3,
  t = "Vijandige overname",
  d = "Deze keer is hij echt te ver gegaan! Het is al erg genoeg dat Gelriz de magnaten wegduwt die door de handelsprinsen zijn aangesteld. Nu probeert hij ook nog een stuk te pakken van de beruchtste piraat van allemaal!$b$bRevilgaz pikt het niet, en hij heeft me gezegd dat ik het probleem op mijn eigen manier moet oplossen.$b$bMijn manier? Diefstal. De geologen van de Venture Co. bij Lake Nazferiti zijn erg geïnteresseerd in die vreemde blauwe kristallen die ze in de mijnen vinden. Breng me monsters van de steen van hun geologen. Het kan me niet schelen wat je moet doen om ze te krijgen.",
  o = "Haal 8 Tumbled Crystals en breng ze terug naar Kebok in Booty Bay.",
  p = "Ik heb die stenen nodig, $n. Op welke manier dan ook! Doe het gewoon, en vertel me de details niet!$b$bHet gaat om resultaten, $n, niets meer en niets minder.",
  c = "Fascinerend. Dat de kristallen met dit procedé zijn geslepen, kan maar één ding betekenen: ze willen ze gebruiken als een soort brandstof of een andere katalysator. Meer weet ik er niet van. De monsters moeten naar Head Chemist Gigglefont worden gestuurd.",
  g = { {"Vijandige overname", "hostile takeover"}, {"te ver gegaan", "gone too far (te ver gaan)"}, {"magnaten", "moguls (magnaat)"}, {"wegduwt", "muscles out (wegduwen)"}, {"handelsprinsen", "trade princes"}, {"aangesteld", "appointed (aanstellen)"}, {"beruchtste", "most notorious (berucht)"}, {"pikt het niet", "won't have it (het niet pikken)"}, {"Diefstal", "theft"}, {"geologen", "geologists (geoloog)"}, {"Op welke manier dan ook", "by whatever means necessary"}, {"procedé", "process"}, {"geslepen", "tumbled, polished (slijpen)"}, {"brandstof", "fuel"}, {"katalysator", "catalyst"} },
},

[577] = { en = "Some Assembly Required", tier = 3,
  t = "Zelf in elkaar zetten",
  d = "Nou, ik heb de basisvorm van de laarzen af, en het gaat goed. Maar de huiden die je hebt gebracht, zijn niet helemaal genoeg voor de binnenlagen.$b$b\"Wat moeten we nu doen, Drizzlik?\" Dat is vast de vraag die je op je lippen hebt. Nou, wat een geluk dat je met Drizzlik praat, want hij gaat je vertellen wat we gaan doen!$b$bDe binnenlagen zie je nooit echt. Dus we halen gewoon wat dikkere, goedkopere huiden van de krokodillen rond Lake Nazferiti om de laarzen op te vullen.",
  o = "Breng 5 Snapjaw Crocolisks Skins naar Drizzlik in Booty Bay.",
  p = "De Excelsior-leren laarzen van Drizzlik: het mooiste vakmanschap, laarzen van honderd procent hoogwaardige krokoliskhuid uit zout water. Er zijn geen betere!$b$bEen schitterendere beschrijving bestaat niet, toch?$b$bBehalve misschien als je die huiden voor me hebt?",
  c = "Mijn laarzen... ze zijn net worstjes, $n. Ze zien er geweldig uit en ze smaken geweldig. Ik vertel je dat er alleen de beste ingrediënten en het beste vlees in zitten, en jij eet het op, en je vindt het heerlijk.$b$bHet is veiliger, en leuker, als je me gewoon vertrouwt en niet te goed vraagt wat er echt in zit.",
  g = { {"in elkaar zetten", "to assemble"}, {"basisvorm", "basic shape"}, {"binnenlagen", "inner layers (binnenlaag)"}, {"op je lippen", "on your lips"}, {"dikkere", "thicker (dik)"}, {"goedkopere", "cheaper (goedkoop)"}, {"op te vullen", "to fill out (opvullen)"}, {"vakmanschap", "workmanship"}, {"hoogwaardige", "high quality (hoogwaardig)"}, {"zout water", "saltwater"}, {"schitterendere", "more glowing (schitterend)"}, {"beschrijving", "description"}, {"worstjes", "sausages (worstje)"}, {"ingrediënten", "ingredients"}, {"heerlijk", "delicious, lovely"} },
},

[188] = { en = "Tiger Mastery", tier = 3,
  t = "Meester in tijgers",
  d = "Dit is de laatste uitdaging die ik je geef. We zijn al weken een tijger op het spoor die heel moeilijk te vinden is. We noemen het beest Sin'Dall. Kijk of je kunt doen wat nog geen $r eerder heeft gedaan: spoor Sin'Dall op en dood haar. Breng me haar poot als bewijs dat het je gelukt is.$b$bHaar opsporen zal niet makkelijk zijn.",
  o = "Ajeck Rouack van Nesingwary's Expedition wil dat je Sin'Dall doodt en terugkomt met haar poot.",
  p = "Hoe gaat de jacht op Sin'Dall?",
  c = "Heel indrukwekkend, dat moet ik zeggen! Jij bent een echte meester-tijgerjager, $N!",
  g = { {"uitdaging", "challenge"}, {"op het spoor", "tracking, on the trail of"}, {"spoor ... op", "hunt down (opsporen)"}, {"poot", "paw"}, {"bewijs", "proof"}, {"gelukt", "succeeded (lukken)"}, {"opsporen", "tracking down"}, {"jacht", "hunt"}, {"indrukwekkend", "impressive"}, {"meester-tijgerjager", "master tiger hunter"} },
},

[210] = { en = "Krazek's Cookery", tier = 3,
  t = "Krazeks kookkunst",
  d = "Ik doe het meeste kookwerk in het kamp. Vroeger was dat veel werk, tot ik een mechanische kookpot kocht van een goblinhandelaar in Booty Bay. De pot is een wonder! Hij heeft me ontelbare uren bespaard... tot hij kapotging!$B$BKun jij de pot voor me terugbrengen naar de goblin, zodat hij hem kan maken? Hij heet Krazek.",
  o = "Breng Krazek's Crock Pot naar Krazek de goblin.",
  p = "Hallo! Heb je iets voor me meegebracht?",
  c = "O, ik zie het al, het is een Krazek's Crock Pot! Een ingenieus stukje werk, maar af en toe springt er een veer of schiet er een tandwiel los. Even kijken wat er met deze mis is...$b$bAha! De stoomlader is doorgeroest, de knokkelpakking is gebarsten en de fobulator mist tanden. Het verbaast me dat de pot in deze toestand nog een raap kon koken!$b$bKan ik hem maken? Natuurlijk kan ik hem maken!$b$bMaar er hangt een prijs aan. O ja, er hangt altijd een prijs aan...",
  g = { {"kookkunst", "cookery"}, {"mechanische", "mechanical (mechanisch)"}, {"kookpot", "cooking pot"}, {"goblinhandelaar", "goblin merchant"}, {"ontelbare", "countless (ontelbaar)"}, {"bespaard", "saved (besparen)"}, {"kapotging", "broke (kapotgaan)"}, {"ingenieus", "ingenious"}, {"veer", "spring"}, {"tandwiel", "gear"}, {"stoomlader", "steam charger"}, {"doorgeroest", "rusted through (doorroesten)"}, {"knokkelpakking", "knuckle-gasket"}, {"gebarsten", "cracked (barsten)"}, {"raap", "turnip"} },
},

[328] = { en = "The Hidden Key", tier = 3,
  t = "De verborgen sleutel",
  d = "In deze papieren wordt Private Thorsen nergens genoemd. Maar in de rug van een van Herods kasboeken zit een klein koperen sleuteltje verstopt.$B$BAls je zijn aantekeningen verder bestudeert, vind je tussen de papieren een paar keer iets over een \"beveiligde geldkist\". De kist staat ergens in de Stockpile, het grottenstelsel achter in Kurzen's Compound.$B$BAls deze beveiligde geldkist wordt gevonden en het kleine koperen sleuteltje hem kan openen, wordt misschien duidelijk hoe Thorsen is ontdekt.",
  o = "Gebruik de Small Brass Key om Bookie Herod's Strongbox te openen.",
  p = "De geldkist is met brons beslagen, heel stevig en heel zwaar.",
  c = "Als je de geldkist opent, is het duidelijk dat Herod hier zijn waardevollere munten en spullen bewaart.",
  g = { {"verborgen", "hidden"}, {"genoemd", "mentioned (noemen)"}, {"rug", "spine, binding"}, {"kasboeken", "ledger books (kasboek)"}, {"koperen", "brass"}, {"verstopt", "hidden (verstoppen)"}, {"aantekeningen", "notes"}, {"bestudeert", "study (bestuderen)"}, {"beveiligde", "secure (beveiligd)"}, {"geldkist", "strongbox"}, {"grottenstelsel", "cavern complex"}, {"ontdekt", "detected, discovered (ontdekken)"}, {"beslagen", "bound, fitted (beslaan)"}, {"stevig", "sturdy"}, {"munten", "coins (munt)"} },
},

[329] = { en = "The Spy Revealed!", tier = 3,
  t = "De spion ontmaskerd!",
  d = "Tussen de kostbaarheden in de geldkist ligt een modderig, haastig gekrabbeld briefje. Het is bijna niet te lezen, maar het lijkt een reisschema van Private Thorsen te zijn. Er staat precies in welke patrouilleroutes hij loopt, met wie hij praat en hoe hij zijn tijd bij de rebellen doorbrengt. Het is ondertekend met maar één letter: -M.$B$BWie dit briefje ook heeft geschreven, moet heel dicht bij Thorsen zijn gebleven. Wie dit briefje heeft geschreven, is de verrader in het kamp van de rebellen.",
  o = "Breng de Muddy Note naar Lieutenant Doren in het Rebel Camp.",
  p = "Heb je ontdekt wie het geheim van Thorsen kende? Is er een verrader onder ons?",
  c = "Dank je, $N. Met dit briefje kunnen we de verrader opsporen en uitschakelen!",
  g = { {"ontmaskerd", "revealed, unmasked (ontmaskeren)"}, {"kostbaarheden", "valuables (kostbaarheid)"}, {"modderig", "muddy"}, {"gekrabbeld", "scribbled (krabbelen)"}, {"reisschema", "itinerary"}, {"patrouilleroutes", "patrol routes"}, {"doorbrengt", "spends (doorbrengen)"}, {"ondertekend", "signed (ondertekenen)"}, {"verrader", "traitor"}, {"onder ons", "among us"}, {"opsporen", "to track down, find"}, {"uitschakelen", "to take out, eliminate"} },
},

[330] = { en = "Patrol Schedules", tier = 3,
  t = "Patrouilleschema's",
  d = "Het briefje dat je me gaf, is ondertekend met een \"-M\"... Ik weet niet wat dat kan betekenen.$B$BMaar... in het briefje staat ook dat deze persoon vorige week dezelfde patrouilleroutes had als Thorsen. Dus wie vorige week samen met Thorsen patrouille liep, moet de verrader zijn!$B$BGa naar Corporal Sethman. Hij regelt de patrouilleschema's en kan je vertellen wie bij Thorsen was.",
  o = "Spreek met Corporal Sethman.",
  c = "O ja, dat kan ik voor je nakijken. Even zien... vorige week stond er...$B$B...nou, Private Merle stond samen met Thorsen ingeroosterd. Ze hadden de hele vorige week dezelfde patrouilletijden.",
  g = { {"Patrouilleschema's", "patrol schedules"}, {"ondertekend", "signed (ondertekenen)"}, {"betekenen", "to mean"}, {"patrouilleroutes", "patrol routes"}, {"patrouille liep", "was on patrol (patrouille lopen)"}, {"verrader", "traitor"}, {"regelt", "handles (regelen)"}, {"nakijken", "to check"}, {"ingeroosterd", "scheduled (inroosteren)"}, {"patrouilletijden", "patrol times"} },
},

[331] = { en = "Report to Doren", tier = 3,
  t = "Breng verslag uit aan Doren",
  d = "Wilde Lieutenant Doren dat je hem verslag uitbracht met die informatie over de patrouilles?",
  o = "Spreek met Lieutenant Doren.",
  c = "Het doet me pijn om te ontdekken dat Merle ons heeft verraden. Hij is altijd een dappere soldaat geweest, en ik dacht dat zijn hart oprecht was. Maar het is een grote opluchting dat we hem hebben ontmaskerd. Met zo'n spion onder ons... zouden we het niet lang volhouden tegen Colonel Kurzen.",
  g = { {"verslag uitbracht", "reported back (verslag uitbrengen)"}, {"patrouilles", "patrols (patrouille)"}, {"Het doet me pijn", "it pains me"}, {"verraden", "betrayed (verraden)"}, {"dappere", "brave (dapper)"}, {"oprecht", "true, sincere"}, {"opluchting", "relief"}, {"ontmaskerd", "found out, unmasked (ontmaskeren)"}, {"spion", "spy"}, {"volhouden", "to last, hold out"} },
