[578] = { en = "The Stone of the Tides", tier = 3,
  t = "De Stone of the Tides",
  d = "Als er echt een goblinmagiër en water-elementalen op het eiland rondspoken, dan kan de Stone of the Tides misschien van mij worden!$b$bIk wil dat jij dit spookeiland vindt... en uitzoekt wat daar aan de hand is. O, en als je misschien meer wilt weten over de Stone of the Tides, breng dan dit briefje naar de Stormwind Library. Daar kunnen ze vast een exemplaar vinden van het boek waarin ik de legende voor het eerst las.$b$bZou Gazban de Stone echt hebben ontdekt...?",
  o = "Vind het spookeiland voor Baron Revilgaz in Booty Bay.",
  p = "De trollen hadden echt geweldige magische voorwerpen, $N. En nu krijg ik misschien de kans om er een toe te voegen aan mijn grote verzameling. Heb je de bron van het gerucht kunnen vinden?",
  c = "Dus de verhalen waren waar! Ongelooflijk!$B$BMaar we moeten een manier vinden om de vloek van de Stone of the Tides te verslaan, als we hem willen ophalen. Een vloek is een zaak van magie; we hebben een van die tovenaars nodig om ons te helpen.",
  e = "Vind het spookeiland",
  g = { {"goblinmagiër", "goblin mage"}, {"water-elementalen", "water elementals"}, {"rondspoken", "haunt (rondspoken)"}, {"spookeiland", "haunted island"}, {"aan de hand", "going on"}, {"exemplaar", "copy"}, {"legende", "legend"}, {"voorwerpen", "objects (voorwerp)"}, {"toe te voegen", "to add (toevoegen)"}, {"verzameling", "collection"}, {"gerucht", "rumor"}, {"Ongelooflijk", "incredible"}, {"vloek", "curse"}, {"tovenaars", "wizards (tovenaar)"} },
},

[601] = { en = "Water Elementals", tier = 3,
  t = "Water-elementalen",
  d = "De water-elementalen zijn ongetwijfeld opgeroepen door Gazban, de goblintovenaar die volgens de geruchten de Stone of the Tides heeft ontdekt. Zoals je misschien weet, vervloekt de Stone of the Tides zijn drager: hij verdwijnt steeds en komt dan weer tevoorschijn...$b$bMisschien kunnen we een manier vinden om de vloek tegen te gaan. Een magiër uit Dalaran kan de magische resten onderzoeken op de armbanden van een van de water-elementalen. Ik heb je nodig om terug te gaan naar het eiland en een paar exemplaren te halen.",
  o = "Verzamel 6 Water Elemental Bracers voor Baron Revilgaz in Booty Bay.",
  p = "Heb je al geluk gehad, $N?",
  c = "Hm, ik heb niet het oog om aan deze armbanden te zien of er iets nuttigs bij zit. Maar ik weet zeker dat er minstens één ons kan helpen. Breng ze naar Dalaran en laat een magiër ernaar kijken.$B$BIk kan Booty Bay tenslotte moeilijk verlaten alleen om met die vermoeiende oude magiërs te kletsen.$B$BNiet dat ik bang ben dat iemand zich naar voren zou dringen om de nieuwe baron te worden. Niemand verraadt Revilgaz en leeft om het na te vertellen.",
  g = { {"ongetwijfeld", "no doubt"}, {"opgeroepen", "summoned (oproepen)"}, {"goblintovenaar", "goblin wizard"}, {"vervloekt", "curses (vervloeken)"}, {"drager", "bearer"}, {"tevoorschijn", "into view (tevoorschijn komen: appear)"}, {"tegen te gaan", "to counteract (tegengaan)"}, {"resten", "residue (rest)"}, {"onderzoeken", "to analyze, examine"}, {"armbanden", "bracers (armband)"}, {"exemplaren", "specimens (exemplaar)"}, {"nuttigs", "useful (iets nuttigs)"}, {"vermoeiende", "tiresome (vermoeiend)"}, {"zich naar voren zou dringen", "would elbow their way in"}, {"na te vertellen", "to tell of it (navertellen)"} },
},

[602] = { en = "Magical Analysis", tier = 3,
  t = "Magische analyse",
  d = "Ik heb gehoord dat de magiërs van Dalaran druk bezig zijn met de wederopbouw van hun verwoeste stad. Maar ik weet zeker dat je er een kunt vinden die wat tijd heeft om naar de armbanden te kijken. Als ik iets van magiërs weet, dan is het dat ze geen magisch raadsel kunnen weerstaan.$b$bNeem de zak met armbanden van de water-elementalen mee en kijk of zij iets duidelijk kunnen maken over de vloek van de Stone. Zoek vooral naar Archmage Ansirem Runeweaver. Ik heb al eerder met hem te maken gehad, en zijn kennis is enorm.",
  o = "Breng de water elemental bracers naar Archmage Ansirem Runeweaver in Dalaran.",
  p = "Als je het niet erg vindt: ik heb het op dit moment nogal druk.",
  c = "De Stone of the Tides? Heel interessant. Het verbaast je misschien, maar ik heb een paar jaar geleden een dik boek geschreven over de legendes van het Gurubashi Empire. Ik weet best veel over de Stone.$B$BMinstens één van deze armbanden lijkt magische resten te hebben die ik kan onderzoeken.$B$BEens kijken wat ik zie...",
  g = { {"analyse", "analysis"}, {"wederopbouw", "reconstruction"}, {"verwoeste", "destroyed (verwoest)"}, {"raadsel", "puzzle"}, {"weerstaan", "to resist"}, {"armbanden", "bracers (armband)"}, {"water-elementalen", "water elementals"}, {"duidelijk ... maken", "shed light on"}, {"vloek", "curse"}, {"te maken gehad", "dealt with (te maken hebben met)"}, {"kennis", "knowledge"}, {"enorm", "vast, enormous"}, {"Als je het niet erg vindt", "if you wouldn't mind"}, {"legendes", "legends (legende)"}, {"resten", "residue (rest)"} },
},

[603] = { en = "Ansirem's Key", tier = 3,
  t = "De sleutel van Ansirem",
  d = "De magiër die de Stone heeft, versterkt de kracht ervan via een soort brandpunt... een altaar of zoiets. Je zou het moeten kunnen verstoren door het te overweldigen.$b$bToevallig weet ik precies wat daarvoor nodig is: een oude dolk, nog een overblijfsel van de trollen. Er is alleen één... klein probleem.$b$bZie je, ik vond de dolk tijdens mijn onderzoek in Stranglethorn. Maar ik gaf hem aan mijn eigenwijze dochter, Catelyn, en die is weggelopen naar Booty Bay om piraat te worden.",
  o = "Praat met Catelyn in Booty Bay.",
  c = "Mijn dolk? Wat ben jij, een soort grappenmaker?$B$BWat? Wil je soms dat ik het verhaal nog eens vertel? Hoe ik van de beste messenvechter van Booty Bay de lachertje van alle piraten werd!$B$BIk verloor een mesgevecht van een van de Bloodsail Buccaneers, echte schoften zijn het!, en hij nam mijn mes mee als buit.$B$BHet is niet zo dat ik als messenvechter kan rondkomen met alleen beledigingen en een scherpe tong...",
  g = { {"versterkt", "amplifies (versterken)"}, {"brandpunt", "focal point"}, {"altaar", "altar"}, {"verstoren", "to disrupt"}, {"overweldigen", "to overpower"}, {"Toevallig", "as it happens"}, {"dolk", "dagger"}, {"overblijfsel", "relic, remnant"}, {"onderzoek", "research"}, {"eigenwijze", "willful, headstrong (eigenwijs)"}, {"grappenmaker", "comedian, joker"}, {"messenvechter", "knife fighter"}, {"lachertje", "laughing stock"}, {"schoften", "bastards (schoft)"}, {"buit", "spoils, loot"}, {"rondkomen", "to get by"}, {"beledigingen", "insults (belediging)"} },
},

[616] = { en = "The Haunted Isle", tier = 3,
  t = "Het spookeiland",
  d = "Baron Revilgaz heeft me gevraagd om mijn oren open te houden voor geruchten over vreemde en ongewone dingen in Booty Bay en Stranglethorn. Meestal geloof ik niet zo in spookverhalen, maar ik hoorde een paar zeelui in de herberg praten over een spookeiland voor de kust. Water-elementalen en een gekke goblinspook, zeggen ze.$b$bAls je met Revilgaz gaat praten, kun je hem dat verhaal dan doorvertellen?",
  o = "Spreek met Baron Revilgaz in Booty Bay.",
  c = "Interessant. Lang geleden heb ik geloof ik eens een boek gelezen waarin stond dat...$b$bAh, natuurlijk, het was een legende van de trollen. Als wat Krazek meldt waar is, kan ik misschien binnenkort de Stone of the Tides toevoegen aan mijn verzameling oude voorwerpen en overblijfselen.",
  g = { {"mijn oren open te houden", "to keep an ear out"}, {"ongewone", "out-of-place, unusual (ongewoon)"}, {"spookverhalen", "ghost stories"}, {"zeelui", "sailors"}, {"herberg", "tavern"}, {"spookeiland", "haunted island"}, {"voor de kust", "off the coast"}, {"goblinspook", "goblin ghost"}, {"doorvertellen", "to relay, pass on"}, {"meldt", "reports (melden)"}, {"verzameling", "collection"}, {"overblijfselen", "relics (overblijfsel)"} },
},

[622] = { en = "Return to Corporal Kaleb", tier = 3,
  t = "Terug naar Corporal Kaleb",
  d = "Terwijl je weg was, heb ik de pot gemaakt die je me bracht. Ik heb er zelfs een extra stoomfluit op gezet, en kijk! Er zit een nieuwe hakker onderin die door beenderen van poten heen snijdt!$B$BJa ja, met Krazek's Crock Pot is elke kok honderd procent tevreden! Ik weet zeker dat de eigenaar blij zal zijn.",
  o = "Breng Krazek's Fixed Pot naar Corporal Kaleb in het Rebel Camp.",
  p = "Hallo, $N. Ben je in Booty Bay geweest? Heeft de goblin Krazek mijn pot gemaakt??",
  c = "Hij is gemaakt! Geweldig, nu kan ik met het avondeten beginnen! Heel erg bedankt, $N.$B$BIk hoop dat het goed ging in Booty Bay. Het kan daar behoorlijk ruw zijn, en... ik heb geruchten gehoord dat de goblins soms dronken zeelui naar hun slavenschepen slepen en ze meenemen naar wie-weet-waar... om wie-weet-wat te doen...",
  g = { {"stoomfluit", "steam whistle"}, {"hakker", "chopper"}, {"onderin", "at the bottom"}, {"beenderen", "bones (been)"}, {"snijdt", "cuts (snijden)"}, {"tevreden", "satisfied, pleased"}, {"eigenaar", "owner"}, {"avondeten", "dinner"}, {"behoorlijk", "pretty, quite"}, {"ruw", "rough"}, {"zeelui", "sailors"}, {"slavenschepen", "slave boats (slavenschip)"}, {"slepen", "drag"} },
},

[627] = { en = "Favor for Krazek", tier = 3,
  t = "Een gunst voor Krazek",
  d = "Er is een berggrot in Drywhisker Gorge, ver naar het noorden in de Arathi Highlands. In die grot zit een zeldzaam erts: bloedsteen. De bloedsteen in deze grot is niet van de hoogste kwaliteit, maar zelfs bloedsteen van lage kwaliteit is waardevol... voor wie weet hoe je het gebruikt.$B$BIk wil er graag wat van hebben.$B$BIk maak je kookpot, maar terwijl ik eraan werk... breng jij me monsters van bloedsteen. Breng me genoeg, dan geef ik je zelfs een bonus.$B$BO, en als je niet kunt mijnen... zoek dan iemand die het wel kan!",
  o = "Breng 4 ladingen Lesser Bloodstone Ore naar Krazek in Booty Bay.",
  p = "Hallo, $N. Heb je de bloedsteen kunnen krijgen?",
  c = "Ah, prachtig! Dat was een grote gunst die je me hebt bewezen.$B$BHier is je betaling...",
  g = { {"gunst", "favor"}, {"berggrot", "mountain cave"}, {"zeldzaam", "rare"}, {"erts", "ore"}, {"bloedsteen", "bloodstone"}, {"kwaliteit", "quality"}, {"waardevol", "valuable"}, {"monsters", "samples (monster)"}, {"mijnen", "to mine"}, {"ladingen", "loads (lading)"}, {"prachtig", "splendid"}, {"bewezen", "done (een gunst bewijzen: do a favor)"}, {"betaling", "payment"} },
},

[192] = { en = "Panther Mastery", tier = 3,
  t = "Meester in panters",
  d = "Nu komt het moeilijke deel. Een echte panterjager laat zijn kunst zien door Shadowmaw Panthers neer te halen, de gevaarlijkste van Stranglethorn. Bewijs ons dat je 10 van deze beesten kunt doden.$b$bAls je denkt dat ze moeilijk op te sporen zijn, wacht dan maar tot je er een probeert te doden....",
  o = "Sir S. J. Erlgadin van Nesingwary's Expedition wil dat je 10 Shadowmaw Panthers doodt.",
  p = "Wat doe jij hier, $N! Je zou door het struikgewas moeten kruipen om 10 Shadowmaw Panthers te doden. Ik dacht dat je jezelf een grootwildjager vond?",
  c = "Goed gedaan, $N!",
  g = { {"panterjager", "panther hunter"}, {"kunst", "skill"}, {"neer te halen", "to drop, bring down (neerhalen)"}, {"gevaarlijkste", "deadliest (gevaarlijk)"}, {"Bewijs", "prove (bewijzen)"}, {"op te sporen", "to track (opsporen)"}, {"struikgewas", "brush, undergrowth"}, {"kruipen", "to crawl"}, {"grootwildjager", "big game hunter"} },
},

[207] = { en = "Kurzen's Mystery", tier = 3,
  t = "Het mysterie van Kurzen",
  d = "Colonel Kurzen was ooit een groot en nobel man. Ik moet ontdekken waardoor hij zo verdorven is geraakt! Misschien staat hij onder invloed van trollenmagie. Om dat te bevestigen, moet ik een paar van hun legendes bestuderen.$B$BIn de trollenruïnes van Stranglethorn zijn 4 stenen tabletten verborgen. Ik moet zien wat er op die tabletten staat! Schrijf hun tekens over en breng de afschriften naar mij.$B$BHet eerste tablet ligt in de Bal'lal Ruins, het tweede in het Vile Reef, en het derde en vierde in de Ruins of Zul'Kunda.",
  o = "Vind de 4 tabletten en breng hun legendes terug naar Brother Nimetz.",
  p = "$N! Heb je de legendes van de trollen? Ik moet hun geheimen kennen!",
  c = "Dank je, $N. Ik ga deze legendes bestuderen om te zien of er een verband is tussen de trollen en het kwaad dat Colonel Kurzen in zijn macht heeft.",
  g = { {"mysterie", "mystery"}, {"nobel", "noble"}, {"verdorven", "depraved"}, {"onder invloed van", "under the sway of"}, {"trollenmagie", "troll magic"}, {"bevestigen", "to confirm"}, {"bestuderen", "to study"}, {"trollenruïnes", "troll ruins"}, {"tabletten", "tablets (tablet)"}, {"verborgen", "hidden"}, {"Schrijf ... over", "transcribe, copy (overschrijven)"}, {"tekens", "markings (teken)"}, {"afschriften", "transcriptions, copies (afschrift)"}, {"verband", "link, connection"}, {"in zijn macht heeft", "has possessed (in zijn macht hebben)"} },
},

[574] = { en = "Special Forces", tier = 3,
  t = "Speciale eenheden",
  d = "Nu veel van zijn gewone troepen zijn uitgedund, moet je het opnemen tegen zijn goed getrainde eenheden. Als ze niet in de wildernis onze rebellensoldaten afslachten, zitten ze diep achter in Kurzen's Compound, in een grot die ze de Stockpile noemen.$B$BIk ken veel van de troepen van Kurzen persoonlijk, en ik weet dat ze bekwaam, trouw en wreed zijn. Dit is geen makkelijke taak die ik je geef, $N.$B$BAls je ze hebt verslagen, breng dan verslag uit aan Lieutenant Doren, mijn commandant. Hij wil jouw verslag uit de eerste hand horen.",
  o = "Dood 10 Kurzen Commandoes en 6 Kurzen Headshrinkers.$B$BBreng verslag uit aan Lieutenant Doren in het Rebel Camp.",
  p = "Sergeant Yohwa zegt me dat je bekwaam en dapper bent, $C. Heb je iets te melden?",
  c = "$N. Sergeant Yohwa vertrouwde op wat je kunt, en ik vertrouw haar. De nederlaag die je de troepen van Kurzen hebt bezorgd, is bijna meer dan we durfden te hopen. Ik was bang dat wij rebellen alleen stonden, en alleen zouden we nooit standhouden tegen het genie van de Colonel.$b$bMisschien is er toch nog hoop dat we het overleven.",
  g = { {"eenheden", "forces, units (eenheid)"}, {"uitgedund", "reduced, thinned out (uitdunnen)"}, {"het opnemen tegen", "to face, take on"}, {"getrainde", "trained (getraind)"}, {"wildernis", "wilderness"}, {"afslachten", "slaughter"}, {"bekwaam", "skilled"}, {"trouw", "loyal"}, {"wreed", "cruel"}, {"verslag uit", "report (verslag uitbrengen)"}, {"commandant", "commanding officer"}, {"uit de eerste hand", "firsthand"}, {"nederlaag", "defeat"}, {"standhouden", "to stand up, hold out"}, {"genie", "brilliance, genius"} },
},

[628] = { en = "Excelsior", tier = 3,
  t = "Excelsior",
  d = "Nu de binnenkant klaar is, hoeft alleen de buitenlaag er nog op. Daarvoor gebruik ik alleen de beste huiden van oude krokodillen. Die gaan langer mee en zijn een beter doek, zeg maar, om de ontwerpen en details aan te brengen die de Excelsior-lijn van Drizzlik zo bijzonder maken.$b$bHet is wel moeilijk om die perfecte huid te vinden. De enige die bij mijn plan past, is de huid van een oude zoutwaterkrokolisk. De oude dieren komen alleen tevoorschijn om de andere zoutwaterkrokodillen te verdedigen. Je moet er dus misschien een paar doden om er een naar buiten te lokken.",
  o = "Breng een Elder Crocolisk Skin naar Drizzlik in Booty Bay.",
  p = "Ik heb ergens gelezen dat de zoutwaterkrokolisken langzaam aan het uitsterven zijn... slecht nieuws voor mijn zaak, hè?$b$bEnfin, ik hoop dat je die huid van de oude zoutwaterkrokolisk voor me hebt!",
  c = "Geweldig! Dankzij jouw hulp kan ik deze bestelling afmaken en met de volgende boot naar Director Riddlevox in Undermine sturen. Zelfs eerder dan gepland!$b$bVoor al je harde werk: ik heb er een paar extra gemaakt, dus neem een paar. Drizzlik trakteert.$b$bEn onthoud: er bestaat geen mooiere laars dan een uit de Excelsior-lijn van Drizzlik!",
  g = { {"binnenkant", "inside"}, {"buitenlaag", "outer layer"}, {"gaan langer mee", "are more durable (langer meegaan)"}, {"doek", "canvas"}, {"zeg maar", "if you will, so to speak"}, {"ontwerpen", "designs (ontwerp)"}, {"aan te brengen", "to apply, add (aanbrengen)"}, {"zoutwaterkrokolisk", "saltwater crocolisk"}, {"verdedigen", "to defend"}, {"lokken", "to lure, draw out"}, {"uitsterven", "dying out"}, {"Enfin", "anyway"}, {"bestelling", "order"}, {"eerder dan gepland", "ahead of schedule"}, {"trakteert", "is treating, it's on (trakteren)"} },
},

[610] = { en = "\"Pretty Boy\" Duncan", tier = 3,
  t = "\"Pretty Boy\" Duncan",
  d = "Heeft mijn VADER je gestuurd? Ik dacht dat die ouwe zeur me nu wel had opgegeven.$b$bHet was niet echt zijn schuld dat ik ben weggelopen. Hij had alleen niet moeten verwachten dat ik een saai leven wilde leiden: muffe boeken lezen en omgaan met grijze, stijve, saaie magiërs!$b$bAls je mijn dolk nodig hebt, moet je hem terughalen bij \"Pretty Boy\" Duncan, een van de Bloodsail Buccaneers. Steek iets tussen zijn schouders, dan geeft hij hem vast wel af.",
  o = "Haal de dolk van Catelyn bij \"Pretty Boy\" Duncan.",
  p = "Niemand had me ooit verslagen, weet je, $N? Ik ben natuurlijk wel eens gesneden; dat hoort bij een mesgevecht. Maar hij gaf me gewoon een klap tegen mijn hoofd, en alles werd zwart. Toen ik bijkwam, lag mijn mes er niet meer.$B$BMisschien zegt mijn bijnaam iets anders, maar ik heb nog steeds een mes nodig om te vechten. En voor mij moet het dat ene zijn.",
  c = "Heb jij Duncan verslagen? Dan ben je blijkbaar minder groen dan je er op het eerste gezicht uitzag.$b$bDat betekent vast ook dat ik je voorlopig niet moet uitdagen voor een gevecht!",
  g = { {"ouwe zeur", "old codger"}, {"opgegeven", "given up on (opgeven)"}, {"schuld", "fault"}, {"saai", "boring"}, {"leiden", "to lead (a life)"}, {"muffe", "musty (muf)"}, {"stijve", "stiff (stijf)"}, {"dolk", "dagger"}, {"Steek", "put, stick (steken)"}, {"schouders", "shoulders (schouder)"}, {"gesneden", "cut (snijden)"}, {"bijkwam", "came to (bijkomen)"}, {"bijnaam", "nickname"}, {"groen", "green, inexperienced"}, {"op het eerste gezicht", "at first glance"}, {"uitdagen", "to challenge"} },
},

[193] = { en = "Panther Mastery", tier = 3,
  t = "Meester in panters",
  d = "Je hebt bijna bewezen dat je een meester-panterjager bent. Er sluipt een panter door de jungle die Bhag'thera heet. Tot nu toe is hij onze groep steeds ontglipt. Kijk of je met je vaardigheden de grote Bhag'thera kunt doden.$b$bBreng me de Fang of Bhag'thera, dan heb je mijn respect verdiend!",
  o = "Sir S. J. Erlgadin van Nesingwary's Expedition wil dat je hem de Fang of Bhag'thera brengt.",
  p = "Bhag'thera kan heel moeilijk te vinden zijn. Hoe gaat de jacht?",
  c = "Dus de grote Bhag'thera is dood! Proost op jou, $N. Je bent echt een machtige $c!",
  g = { {"bewezen", "proven (bewijzen)"}, {"meester-panterjager", "master panther hunter"}, {"sluipt", "prowls (sluipen)"}, {"Tot nu toe", "so far"}, {"ontglipt", "eluded, slipped away (ontglippen)"}, {"vaardigheden", "skills (vaardigheid)"}, {"respect", "respect"}, {"verdiend", "earned (verdienen)"}, {"jacht", "hunt"}, {"Proost op jou", "cheers to you"}, {"machtige", "mighty (machtig)"} },
},

[202] = { en = "Colonel Kurzen", tier = 3,
  t = "Colonel Kurzen",
  d = "Je hebt jezelf keer op keer bewezen, en je vindingrijkheid lijkt zelfs die van Kurzen te evenaren. Misschien ben jij de redding van onze groep rebellen... als je het tegen Kurzen kunt opnemen en kunt winnen!$B$BHij geeft zijn mannen bevelen vanuit de diepte van de Stockpile. Je moet die grot in, je een weg banen langs zijn verdedigers en het opnemen tegen Kurzen en zijn leiders.$B$BVaarwel, $N. Mijn hoop, en het lot van mijn mannen, gaan met je mee.",
  o = "Dood 6 Kurzen Elite en 4 Kurzen Subchiefs, en breng Kurzen's Head naar Lieutenant Doren in het Rebel Camp.",
  p = "Durf ik te hopen dat Kurzen en zijn verdedigers dood zijn, $N?",
  c = "Ik durfde de berichten niet te geloven, maar je brengt ons het bewijs dat... Kurzen en zijn leiders verslagen zijn. Je hebt ons gered!$B$BDeze jungles zitten vol gevaren van allerlei soort, maar geen ervan had het wrede verstand van Kurzen. Nu hij weg is, kunnen we allemaal weer wat vrijer ademen.",
  g = { {"keer op keer", "time and again"}, {"vindingrijkheid", "resourcefulness"}, {"evenaren", "to rival, equal"}, {"redding", "salvation"}, {"het ... opnemen", "to take on (het opnemen tegen)"}, {"bevelen", "commands, orders (bevel)"}, {"je een weg banen", "to fight your way through"}, {"verdedigers", "defenders (verdediger)"}, {"Vaarwel", "farewell"}, {"lot", "fate"}, {"Durf", "dare (durven)"}, {"bewijs", "proof"}, {"gered", "saved (redden)"}, {"verstand", "intellect, mind"}, {"vrijer ademen", "breathe easier"} },
},

[205] = { en = "Troll Witchery", tier = 3,
  t = "Trollenhekserij",
  d = "Terwijl ik de legendes bestudeer die je hebt gevonden, verzamel jij voor mij voorwerpen van kwaadaardige trollenmagie. Ga naar het gebied van de Skullsplitter-trollen, een tweede stam ver in het zuiden, en haal Skullsplitter Fetishes bij hun Witchdoctors en Mystics.",
  o = "Breng 4 Skullsplitter Fetishes naar Brother Nimetz in het Rebel Camp.",
  p = "Heb je die fetisjen, $N? Misschien zit daarin het geheim van Kurzens verval... Ik moet het weten!",
  c = "Dank je. Ik ga deze fetisjen bestuderen en kijken of ze het geheim bevatten van hoe Kurzen tot het kwaad is vervallen.",
  g = { {"Trollenhekserij", "troll witchery"}, {"legendes", "legends (legende)"}, {"bestudeer", "study (bestuderen)"}, {"voorwerpen", "implements, objects (voorwerp)"}, {"kwaadaardige", "evil (kwaadaardig)"}, {"trollenmagie", "troll magic"}, {"gebied", "territory"}, {"stam", "tribe"}, {"fetisjen", "fetishes (fetisj)"}, {"verval", "degradation, decline"}, {"bevatten", "hold, contain"}, {"vervallen", "fallen (vervallen tot)"} },
},

[338] = { en = "The Green Hills of Stranglethorn", tier = 3,
  t = "The Green Hills of Stranglethorn",
  d = "Meester Nesingwary wordt zo boos als hij erachter komt!$b$bHij vertrouwde me zijn manuscript toe om het na te lezen: zijn roman The Green Hills of Stranglethorn. Alles ging goed, maar toen blies een harde windvlaag door het kamp en vlogen de bladzijden overal heen!$b$bIk heb de meeste bladzijden kunnen verzamelen, maar er liggen er nog veel verspreid door de jungle. Verzamel de bladzijden om alle vier de hoofdstukken compleet te maken.$b$bIk help je om ze te ordenen. Breng de hoofdstukken naar mij als je ze alle vier hebt.",
  o = "Verzamel de ontbrekende bladzijden van het manuscript van The Green Hills of Stranglethorn. Als alle vier de hoofdstukken compleet zijn, breng ze dan naar Barnil.",
  p = "Heb je de hoofdstukken al bij elkaar, $N?",
  c = "Je hebt me echt een hoop problemen bespaard, $n! Ik kan je niet genoeg bedanken. Het duurt nu vast niet lang meer voordat we het boek van meester Nesingwary in bibliotheken over de hele wereld zien!",
  g = { {"erachter komt", "finds out (erachter komen)"}, {"vertrouwde ... toe", "entrusted (toevertrouwen)"}, {"manuscript", "manuscript"}, {"na te lezen", "to proofread (nalezen)"}, {"roman", "novel"}, {"windvlaag", "gust of wind"}, {"bladzijden", "pages (bladzijde)"}, {"verspreid", "strewn, scattered (verspreiden)"}, {"hoofdstukken", "chapters (hoofdstuk)"}, {"compleet", "complete"}, {"ordenen", "to organize"}, {"ontbrekende", "missing (ontbrekend)"}, {"bespaard", "saved (besparen)"}, {"bibliotheken", "libraries (bibliotheek)"} },
},

[339] = { en = "Chapter I", tier = 3,
  t = "Hoofdstuk I",
  d = "Hoofdstuk I was heel boeiend! Meester Nesingwary schetst de achtergrond van het verhaal en noemt zijn jachtgenoten, ook mij! $b$bMaar daar gaat het niet om. Even kijken welke bladzijden nog ontbreken. Zo te zien liggen bladzijde 1, 4, 6 en 8 nog ergens in de jungle!",
  o = "Breng bladzijde 1, 4, 6 en 8 van Nesingwary's The Green Hills of Stranglethorn naar Barnil Stonepot om Hoofdstuk I compleet te maken.",
  p = "Je hebt bladzijde 1, 4, 6 en 8 zeker nog niet kunnen vinden? Meer dan die vier hebben we niet nodig om Hoofdstuk I weer in elkaar te zetten.",
  c = "Eindelijk! Hoofdstuk I is compleet!",
  g = { {"Hoofdstuk", "chapter"}, {"boeiend", "riveting, gripping"}, {"schetst", "sets, sketches (schetsen)"}, {"achtergrond", "backdrop, background"}, {"jachtgenoten", "hunting companions (jachtgenoot)"}, {"daar gaat het niet om", "that's beside the point"}, {"bladzijden", "pages (bladzijde)"}, {"ontbreken", "are missing"}, {"in elkaar te zetten", "to piece together (in elkaar zetten)"}, {"compleet", "complete"} },
},

[340] = { en = "Chapter II", tier = 3,
  t = "Hoofdstuk II",
  d = "Hoofdstuk II stond boordevol spannende verhalen over het jagen op panters en tijgers. Ik kan mezelf wel voor mijn kop slaan dat ik de bladzijden heb laten wegwaaien! $b$b Zo te zien heb ik alle bladzijden teruggevonden, behalve bladzijde 10, 11, 14 en 16.",
  o = "Breng bladzijde 10, 11, 14 en 16 van Nesingwary's The Green Hills of Stranglethorn naar Barnil Stonepot om Hoofdstuk II compleet te maken.",
  p = "We hebben nog bladzijde 10, 11, 14 en 16 nodig om Hoofdstuk II compleet te maken, $N.",
  c = "Hoofdstuk II is eindelijk compleet! Goed gedaan!",
  g = { {"Hoofdstuk", "chapter"}, {"boordevol", "chock full"}, {"spannende", "exciting (spannend)"}, {"mezelf wel voor mijn kop slaan", "could kick myself"}, {"wegwaaien", "blow away"}, {"teruggevonden", "recovered (terugvinden)"}, {"behalve", "except"}, {"compleet", "complete"} },
},

[341] = { en = "Chapter III", tier = 3,
  t = "Hoofdstuk III",
  d = "Hoofdstuk III was mijn favoriet. Het vertelt over de eerste vangst van Sir Erlgadin en Lady Rouack met een dwergengeweer. En het einde van Hoofdstuk III, nou, wat een spannend open einde!$b$bHet lijkt erop dat we nog bladzijde 18, 20, 21 en 24 nodig hebben om het hoofdstuk af te maken. Die bladzijden liggen daar ergens...",
  o = "Breng bladzijde 18, 20, 21 en 24 van Nesingwary's The Green Hills of Stranglethorn naar Barnil Stonepot om Hoofdstuk III compleet te maken.",
  p = "Al geluk gehad met bladzijde 18, 20, 21 of 24? Meer hebben we niet nodig om Hoofdstuk III weer in elkaar te zetten.",
  c = "Pfoe! Goed werk, $N. Hoofdstuk III is weer helemaal compleet!",
  g = { {"Hoofdstuk", "chapter"}, {"favoriet", "favourite"}, {"vangst", "kill, catch"}, {"dwergengeweer", "dwarven rifle"}, {"spannend open einde", "cliffhanger"}, {"Het lijkt erop", "it looks like"}, {"af te maken", "to finish (afmaken)"}, {"in elkaar te zetten", "to piece together (in elkaar zetten)"}, {"Pfoe", "phew"}, {"compleet", "complete"} },
},

[342] = { en = "Chapter IV", tier = 3,
  t = "Hoofdstuk IV",
  d = "Ah, Hoofdstuk IV: de grote finale! En wat een einde was het! $b$bWe missen voor dit hoofdstuk nog maar drie bladzijden. We hebben bladzijde 25, 26 en 27 nodig om Hoofdstuk IV weer in elkaar te zetten.",
  o = "Breng bladzijde 25, 26 en 27 van Nesingwary's The Green Hills of Stranglethorn naar Barnil Stonepot om Hoofdstuk IV compleet te maken.",
  p = "We hebben nog maar drie bladzijden nodig om Hoofdstuk IV af te maken, $N. Heb je bladzijde 25, 26 of 27 al?",
  c = "Geweldig! Hoofdstuk IV is nu klaar!",
  g = { {"Hoofdstuk", "chapter"}, {"finale", "finale"}, {"missen", "are missing (missen)"}, {"bladzijden", "pages (bladzijde)"}, {"in elkaar te zetten", "to piece together (in elkaar zetten)"}, {"af te maken", "to finish (afmaken)"} },
},

